t.script:
function getDeviceFingerprint() {
    // Identifiant persistant du navigateur, stocké côté client.
    var key = 'school_device_fingerprint';
    var fp = localStorage.getItem(key);
    if (!fp) {
        fp = 'dev-' + crypto.randomUUID();
        localStorage.setItem(key, fp);
    }
    return fp;
}

var btn = document.getElementById('confirm_btn');
if (btn) btn.addEventListener('click', function () {
    var msg = document.getElementById('status_msg');
    if (!navigator.geolocation) {
        msg.textContent = "Géolocalisation non disponible sur cet appareil.";
        msg.className = 'alert';
        msg.classList.add('alert-danger');
        return;
    }
    navigator.geolocation.getCurrentPosition(function (pos) {
        fetch('/school/attendance/confirm', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    token: '',
                    latitude: pos.coords.latitude,
                    longitude: pos.coords.longitude,
                    device_fingerprint: getDeviceFingerprint(),
                    accuracy: pos.coords.accuracy,
                },
            }),
        }).then(r => r.json()).then(data => {
            var result = data.result || {};
            msg.className = 'alert';
            if (result.error) {
                msg.textContent = result.error;
                msg.classList.add('alert-danger');
            } else if (result.state === 'rejected') {
                msg.textContent = "Présence refusée : " + result.flag_reason + ". Rapprochez-vous de la salle puis réessayez.";
                msg.classList.add('alert-danger');
            } else if (result.state === 'valid') {
                msg.textContent = "Présence confirmée !";
                msg.classList.add('alert-success');
            } else {
                msg.textContent = "Présence enregistrée mais à vérifier : " + result.flag_reason;
                msg.classList.add('alert-warning');
            }
        });
    }, function () {
        msg.textContent = "Merci d'autoriser la géolocalisation pour confirmer votre présence.";
        msg.className = 'alert';
        msg.classList.add('alert-danger');
    }, {enableHighAccuracy: true, timeout: 15000});
});
